-- Acessos por grupo: cada pessoa fica num grupo (access_groups, ligado a cargos do cadastro); o grupo libera as
-- páginas do menu (access_group_pages); o que for diferente fica como exceção da pessoa (user_page_access). O perfil
-- (user_roles) passa a ser só o alcance dos dados. can_access_page: exceção > grupo > perfil > padrão.
-- Os grupos e exceções abaixo foram calculados dos acessos de 18/11/2026 (página a página, acesso final idêntico).
CREATE TABLE IF NOT EXISTS public.access_groups (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key text NOT NULL UNIQUE,
  name text NOT NULL,
  cargos text[] NOT NULL DEFAULT '{}',
  sort int NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.access_group_pages (
  group_id uuid NOT NULL REFERENCES public.access_groups(id) ON DELETE CASCADE,
  path text NOT NULL,
  allowed boolean NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (group_id, path)
);
ALTER TABLE public.users_profiles ADD COLUMN IF NOT EXISTS access_group_id uuid REFERENCES public.access_groups(id) ON DELETE SET NULL;
ALTER TABLE public.access_groups ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.access_group_pages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS access_groups_select ON public.access_groups;
CREATE POLICY access_groups_select ON public.access_groups FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS access_groups_write ON public.access_groups;
CREATE POLICY access_groups_write ON public.access_groups FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
DROP POLICY IF EXISTS access_group_pages_select ON public.access_group_pages;
CREATE POLICY access_group_pages_select ON public.access_group_pages FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS access_group_pages_write ON public.access_group_pages;
CREATE POLICY access_group_pages_write ON public.access_group_pages FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.access_groups, public.access_group_pages TO authenticated;

CREATE OR REPLACE FUNCTION public.can_access_page(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
  WITH r AS (
    SELECT CASE
      WHEN public.has_role(auth.uid(),'admin') THEN 'admin'
      WHEN public.has_role(auth.uid(),'programmer') THEN 'programmer'
      WHEN public.has_role(auth.uid(),'coordenador') THEN 'coordenador'
      WHEN public.has_role(auth.uid(),'encarregado') THEN 'encarregado'
      ELSE 'viewer' END::app_role AS role
  )
  SELECT auth.uid() IS NOT NULL AND COALESCE(
    (SELECT u.allowed FROM public.user_page_access u WHERE u.user_id = auth.uid() AND u.path = _path),
    (SELECT gp.allowed FROM public.users_profiles up JOIN public.access_group_pages gp ON gp.group_id = up.access_group_id WHERE up.id = auth.uid() AND gp.path = _path),
    (SELECT a.allowed FROM public.role_page_access a, r WHERE a.role = r.role AND a.path = _path),
    (SELECT CASE WHEN r.role = 'encarregado' THEN _path LIKE '/externo%'
                 WHEN r.role = 'coordenador' THEN false
                 ELSE true END FROM r)
  )
$function$;

-- Grupo pelo cargo: colaborador com o mesmo primeiro nome e todas as palavras do usuário (único), cargo sem N1–N4.
CREATE OR REPLACE FUNCTION public.access_group_by_cargo(_user uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  WITH u AS (SELECT regexp_split_to_array(trim(translate(upper(full_name), 'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ', 'AAAAAEEEEIIIIOOOOOUUUUC')), '\s+') w FROM users_profiles WHERE id = _user AND coalesce(trim(full_name), '') <> ''),
  c AS (SELECT c.position_id FROM collaborators c, u WHERE c.status = 'active'
        AND (regexp_split_to_array(trim(translate(upper(c.full_name), 'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ', 'AAAAAEEEEIIIIOOOOOUUUUC')), '\s+'))[1] = u.w[1]
        AND u.w <@ regexp_split_to_array(trim(translate(upper(c.full_name), 'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ', 'AAAAAEEEEIIIIOOOOOUUUUC')), '\s+')),
  p AS (SELECT regexp_replace(trim(p.name), '\s+N[1-4]$', '') cargo FROM positions p WHERE p.id = (SELECT position_id FROM c) AND (SELECT count(*) FROM c) = 1)
  SELECT g.id FROM access_groups g, p WHERE EXISTS (SELECT 1 FROM unnest(g.cargos) x WHERE lower(x) = lower(p.cargo)) ORDER BY g.sort LIMIT 1
$$;
-- Ao ativar um usuário sem grupo, o grupo vem do cargo.
CREATE OR REPLACE FUNCTION public.users_profiles_default_group() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.active AND NOT coalesce(OLD.active, false) AND NEW.access_group_id IS NULL THEN
    NEW.access_group_id := public.access_group_by_cargo(NEW.id);
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_users_profiles_default_group ON public.users_profiles;
CREATE TRIGGER trg_users_profiles_default_group BEFORE UPDATE OF active ON public.users_profiles FOR EACH ROW EXECUTE FUNCTION public.users_profiles_default_group();

